svg.script:
(function() {
  const svg = document.querySelector('svg');
  const flipPage = document.getElementById('flip-page');
  const flipShadow = document.getElementById('flip-shadow');
  const flipHighlight = document.getElementById('flip-highlight');
  const hitLeft = document.getElementById('hit-left');
  const hitRight = document.getElementById('hit-right');

  const SPINE_X = 600;
  const SPINE_TOP_Y = 132;
  const SPINE_BOT_Y = 624;

  let isDragging = false;
  let dragDirection = 1;
  let dragStartX = 0;
  let currentProgress = 0;
  let animFrameId = null;

  function lerp(a, b, t) {
    return a + (b - a) * t;
  }

  function renderFlipAt(t) {
    if (0.002 >= t || t >= 0.998) {
      flipPage.setAttribute('opacity', '0');
      flipShadow.setAttribute('opacity', '0');
      flipHighlight.setAttribute('opacity', '0');
      return;
    }

    const arch = Math.sin(t * Math.PI);
    const tTop = Math.pow(t, 0.92);
    const tBot = Math.pow(t, 1.08);

    const outerTopX = lerp(1065, 135, tTop);
    const outerTopY = 114 - arch * 68;

    const outerBotX = lerp(1086, 114, tBot);
    const outerBotY = 592 - arch * 54;

    const ctrl1X = lerp(735, 465, t);
    const ctrl1Y = 80 - arch * 52;

    const ctrl2X = lerp(955, 245, tTop);
    const ctrl2Y = 84 - arch * 75;

    const ctrlBot1X = lerp(955, 245, tBot);
    const ctrlBot1Y = 568 - arch * 65;

    const ctrlBot2X = lerp(735, 465, t);
    const ctrlBot2Y = 570 - arch * 42;

    const outerMidX = (outerTopX + outerBotX) / 2 + (0.5 - t) * arch * 38;
    const outerMidY = (outerTopY + outerBotY) / 2 - arch * 15;

    const pagePath = [
      'M', SPINE_X, SPINE_TOP_Y,
      'C', ctrl1X, ctrl1Y, ctrl2X, ctrl2Y, outerTopX, outerTopY,
      'Q', outerMidX, outerMidY, outerBotX, outerBotY,
      'C', ctrlBot1X, ctrlBot1Y, ctrlBot2X, ctrlBot2Y, SPINE_X, SPINE_BOT_Y,
      'Z'
    ].join(' ');

    const shadowOffset = (0.5 - t) * 55 * arch;
    const shadowPath = [
      'M', SPINE_X, SPINE_TOP_Y + 6,
      'C', ctrl1X + shadowOffset, ctrl1Y + 25, ctrl2X + shadowOffset, ctrl2Y + 32, outerTopX + shadowOffset, outerTopY + 28,
      'Q', outerMidX + shadowOffset, outerMidY + 28, outerBotX + shadowOffset, outerBotY + 24,
      'C', ctrlBot1X + shadowOffset, ctrlBot1Y + 24, ctrlBot2X + shadowOffset, ctrlBot2Y + 18, SPINE_X, SPINE_BOT_Y + 4,
      'Z'
    ].join(' ');

    const highlightXTop = lerp(SPINE_X, outerTopX, 0.55);
    const highlightYTop = lerp(SPINE_TOP_Y, outerTopY, 0.55) - arch * 38;
    const highlightXBot = lerp(SPINE_X, outerBotX, 0.55);
    const highlightYBot = lerp(SPINE_BOT_Y, outerBotY, 0.55) - arch * 30;
    const highlightPath = ['M', highlightXTop, highlightYTop, 'L', highlightXBot, highlightYBot].join(' ');

    const edgeFade = Math.min(1, Math.min(t * 12, (1 - t) * 12));

    flipPage.setAttribute('d', pagePath);
    flipPage.setAttribute('opacity', edgeFade.toFixed(3));
    flipPage.setAttribute('fill', 0.5 > t ? 'url(#flip-page-grad)' : 'url(#flip-back-grad)');

    flipShadow.setAttribute('d', shadowPath);
    flipShadow.setAttribute('opacity', (arch * 0.38 * edgeFade).toFixed(3));

    flipHighlight.setAttribute('d', highlightPath);
    flipHighlight.setAttribute('opacity', (arch * 0.45 * edgeFade).toFixed(3));
  }

  function getSvgX(clientX, clientY) {
    const pt = svg.createSVGPoint();
    pt.x = clientX;
    pt.y = clientY;
    const ctm = svg.getScreenCTM();
    if (!ctm) return SPINE_X;
    return pt.matrixTransform(ctm.inverse()).x;
  }

  function animateFlip(fromT, toT, duration) {
    if (animFrameId) cancelAnimationFrame(animFrameId);
    const startTime = performance.now();

    function step(now) {
      const elapsed = now - startTime;
      const raw = Math.min(1, elapsed / duration);
      const eased = 0.5 > raw
        ? 4 * raw * raw * raw
        : 1 - Math.pow(-2 * raw + 2, 3) / 2;

      currentProgress = lerp(fromT, toT, eased);
      renderFlipAt(currentProgress);

      if (1 > raw) {
        animFrameId = requestAnimationFrame(step);
      } else {
        renderFlipAt(toT);
        animFrameId = null;
      }
    }

    animFrameId = requestAnimationFrame(step);
  }

  function startInteraction(e, side) {
    e.preventDefault();
    if (animFrameId) {
      cancelAnimationFrame(animFrameId);
      animFrameId = null;
    }
    isDragging = true;

    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const clientY = e.touches ? e.touches[0].clientY : e.clientY;
    dragStartX = getSvgX(clientX, clientY);

    if (side === 'right') {
      dragDirection = 1;
      currentProgress = 0.02;
    } else {
      dragDirection = -1;
      currentProgress = 0.98;
    }
    renderFlipAt(currentProgress);
  }

  function moveInteraction(e) {
    if (!isDragging) return;
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const clientY = e.touches ? e.touches[0].clientY : e.clientY;
    const svgX = getSvgX(clientX, clientY);

    const mappedT = 1 - Math.max(0.01, Math.min(0.99, (svgX - 135) / (1065 - 135)));
    currentProgress = mappedT;
    renderFlipAt(currentProgress);
  }

  function endInteraction(e) {
    if (!isDragging) return;
    isDragging = false;

    const clientX = e.changedTouches ? e.changedTouches[0].clientX : e.clientX;
    const clientY = e.changedTouches ? e.changedTouches[0].clientY : e.clientY;
    const endX = getSvgX(clientX, clientY);
    const movedDist = Math.abs(endX - dragStartX);

    if (25 > movedDist) {
      if (dragDirection === 1) {
        animateFlip(0.02, 1, 680);
      } else {
        animateFlip(0.98, 0, 680);
      }
      return;
    }

    if (dragDirection === 1) {
      const target = currentProgress > 0.3 ? 1 : 0;
      const duration = Math.max(220, Math.abs(target - currentProgress) * 600);
      animateFlip(currentProgress, target, duration);
    } else {
      const target = 0.7 > currentProgress ? 0 : 1;
      const duration = Math.max(220, Math.abs(target - currentProgress) * 600);
      animateFlip(currentProgress, target, duration);
    }
  }

  hitRight.addEventListener('mousedown', function(e) { startInteraction(e, 'right'); });
  hitLeft.addEventListener('mousedown', function(e) { startInteraction(e, 'left'); });
  window.addEventListener('mousemove', moveInteraction);
  window.addEventListener('mouseup', endInteraction);

  hitRight.addEventListener('touchstart', function(e) { startInteraction(e, 'right'); }, { passive: false });
  hitLeft.addEventListener('touchstart', function(e) { startInteraction(e, 'left'); }, { passive: false });
  window.addEventListener('touchmove', moveInteraction, { passive: false });
  window.addEventListener('touchend', endInteraction);
})();
